// Managed loop: delegate, execute, record, repeat within budget (plain JS)
async function runManaged(workers, manager, initial, budget = { rounds: 6 }) {
  let state = { ...initial, history: [] };
  for (let round = 0; round < budget.rounds; round++) {
    const assignment = manager(state); // { worker, task } | { done: true }
    if (assignment.done) return { ok: true, state, rounds: round };
    state.history.push(assignment.worker);
    const out = await workers[assignment.worker](assignment.task, state);
    Object.assign(state, out);
  }
  return { ok: false, reason: "budget-exhausted", state, rounds: budget.rounds };
}
// Budget exhaustion is a designed terminal (escalate), never a hang.

// Done-condition patterns (choose per workflow, state explicitly)
