// Sync twin of the lesson runner (same budget logic, no awaits — playground-safe)
function runManaged(workers, manager, initial, budget) {
  budget = budget || { rounds: 6 };
  let state = { ...initial, history: [] };
  for (let round = 0; round < budget.rounds; round++) {
    const a = manager(state);
    if (a.done) return { ok: true, rounds: round, state };
    state.history.push(a.worker);
    Object.assign(state, workers[a.worker](a.task, state));
  }
  return { ok: false, reason: 'budget-exhausted', rounds: budget.rounds };
}
const workers = {
  checker: () => ({ checked: true }),
  drafter: () => ({ draft: 'done', done: true }),
};
function manager(s) {
  if (!s.checked) return { worker: 'checker' };
  if (!s.draft) return { worker: 'drafter' };
  return { done: true };
}
const r1 = runManaged(workers, manager, {});
console.log('ok=' + r1.ok + ' rounds=' + r1.rounds);
console.log('history=' + r1.state.history.join(','));
const r2 = runManaged(workers, () => ({ worker: 'checker' }), {}, { rounds: 3 });
console.log('loop guard: ok=' + r2.ok + ' reason=' + r2.reason);

